from expansion_author import command, question as q, source, state, write_batch
artifact=[dict(title='Offline cloud planning and restore companion',path='labs/cloud-planning.py')]
def cmd(case):return command('python labs/cloud-planning.py --case '+case,'Evaluate only the authored offline model; the cost case also restores an owned temporary plan file.','Read baseline/fault/recovery and scope. No credentials, provider API, real prices or paid resources are used.')
refs=[source('AWS shared responsibility model','https://aws.amazon.com/compliance/shared-responsibility-model/'),source('AWS IAM security best practices','https://docs.aws.amazon.com/IAM/latest/UserGuide/best-practices.html'),source('AWS fault isolation: availability zones','https://docs.aws.amazon.com/whitepapers/latest/aws-fault-isolation-boundaries/availability-zones.html'),source('AWS Budgets','https://docs.aws.amazon.com/cost-management/latest/userguide/budgets-managing-costs.html'),source('Terraform sensitive data','https://developer.hashicorp.com/terraform/language/manage-sensitive-data'),source('AWS reliability: disaster recovery','https://docs.aws.amazon.com/wellarchitected/latest/reliability-pillar/plan-for-disaster-recovery-dr.html')]
lessons=[dict(id='ADD-CLOUD-001',subtitle='Assign responsibility and trace identity independently of reachability.',minutes=45,
definition='Cloud services divide operational responsibility between a provider and a customer according to the selected service. Identity and access management governs who may perform which operations, while cloud networking governs delivery paths and traffic policy. Neither service branding nor network reachability alone establishes authorization or data protection.',
purpose='Design a small cloud workload by naming the owner of every security and recovery task. Trace a request through its principal, credentials, permitted action, resource and network path. Use managed services deliberately without assuming that provider operation removes the customer’s obligations for data, identity, configuration or recovery.',
mental='A managed service resembles renting a staffed facility: some building operations are handled for you, but your keys, occupants, contents and usage rules remain your responsibility. The exact boundary changes with the service. A VM, object store and managed database do not share an identical patching or backup contract.',
components=['Responsibility register: provider-managed layers and customer-owned configuration/data/tasks for each chosen service.','Principal and credentials: human or workload identity with a lifecycle, authentication method and scoped authority.','Authorization context: action, resource and applicable policies/conditions, with explicit denials and scope.','Network path: subnet routes, gateways/endpoints, traffic controls, naming and return path.','Audit/recovery: accountable changes, protected logs and a usable path to recovery credentials.'],
mechanism=['Choose the service model, then assign concrete tasks such as guest OS patching, application updates, data classification, access policy and backup validation. Read the actual service documentation rather than importing a VM responsibility model into every managed service.','Identify the acting principal from the workload or operator context. Prefer short-lived scoped credentials where supported, and distinguish authentication from permission to perform a specific resource action.','Evaluate the relevant authorization layers. The companion uses an intentionally tiny exact action/resource-pair model with explicit-deny precedence and default denial; it is not an implementation of a provider’s full policy evaluation.','Trace network delivery separately: destination resolution, route, endpoint/gateway, traffic controls and return path. A private address does not imply correct identity policy, while an allowed identity does not create a usable network path.','Verify both allowed and denied operations on a disposable owned target before operational acceptance. Retain the exact identity and policy revision used for the observation; never paste access tokens into a report.'],
flow=[('Assign','List provider and customer tasks for the selected service.'),('Identify','Establish principal, credential lifetime and requested operation.'),('Trace','Evaluate policy and network path as separate boundaries.'),('Verify','Test intended access and intended denial with scoped evidence.')],
comparison=[['Authentication','Establishes a principal under an identity system','Does not automatically permit every operation'],['Authorization','Permits or denies a specific operation','Depends on the full applicable policy context'],['Network reachability','Packets can traverse an allowed path','Does not prove application authorization'],['Managed service','Provider operates specified layers','Customer duties remain service-specific']],
example='The offline model initially allows read on lesson/receipt. Adding an explicit deny for that same pair rejects it despite the allow. Removing that deny restores the original result, while write on the same resource remains implicitly denied. This teaches narrow reasoning; it does not cover provider roles, condition keys, resource policies or organization-level controls.',
commands=[cmd('access')],
configuration='For a disposable account/project, identify the exact principal, permitted action/resource and expected negative test before changing policy. Save the prior revision and validate with provider-supported tools and actual bounded operations. Restore only the owned policy revision on failure. Do not fix an access error by granting administrator privileges or opening every network source.',
production='Separate human administration from workload identity and centralize credential lifecycle and audit ownership. Review stale grants and unused access. Record which service supplies encryption, logging and backup features and which customer settings activate or govern them.',
troubleshooting=[('Timeout reaching a private endpoint','Inspect DNS, route, endpoint policy and traffic controls; the symptom alone is not an IAM conclusion.'),('AccessDenied after successful connection','Inspect actual principal, action/resource and all relevant policy constraints.'),('Works for administrator but not workload','Compare identity and policy context rather than copying the administrator’s broad rights.'),('Recovery account cannot decrypt backup','Include key policy, credential access and independent recovery ownership in the plan.')],
security='Keep credentials out of code, screenshots and state exports. Favor scoped workload identities and short-lived access where the service supports them. A private network is useful defense but cannot replace authorization, encryption or data classification.',
performance='Managed endpoints, gateways and cross-zone paths have latency and capacity characteristics that need measurement. Do not turn a permission diagnosis into a load test. Bounded positive and negative requests are sufficient for access validation.',
mistakes=['Assuming managed means no customer security work.','Treating a private subnet as authorization.','Granting administrator access to resolve every denial.','Using the teaching model as an IAM policy engine.'],ports='Cloud identity/API calls commonly use HTTPS, but service data paths and private endpoints have their own configuration. The companion uses no sockets, API endpoints or credential files.',prerequisites=['ADD-INFRA-003','ADD-APP-002'],related=['s9-g1-t3','ADD-CLOUD-002'],artifacts=artifact,sources=refs[:2],
lab=dict(objective='Separate a simple authorization decision from a cloud responsibility and networking review.',requirements='Python 3.10+ and a notebook. No cloud account, SDK or credentials are needed.',topology=['Principal requests read','Exact resource lesson/receipt','Allow and deny sets','Independent network path outside model'],steps=['Predict the baseline, explicit-deny fault, recovery and unrelated write results.','Run the access case and compare allow/explicit-deny/allow plus implicit-deny for write.','Write a responsibility table for a VM and a managed object store, including patching, data, identity and restore testing.','Draw an application-to-private-service route and identify which observations address network versus authorization.','Design a guided positive and negative access test with exact principal/action/resource and cleanup.','List policy features excluded from the companion before drawing any target conclusion.'],verification='The four decisions match the declared exact-pair rules. The notebook names customer duties and does not claim a cloud policy or network was exercised.',troubleshooting='A real access failure needs provider-specific evaluation and observed target context. Do not copy the toy rule set into production or remove explicit denies without understanding their purpose.',challenge='A role can read an encrypted object but cannot decrypt its key. Explain why resource read permission alone may not establish usable data access.',cleanup='The access model has no side effects. Guided cloud work must restore only owned policies and revoke temporary access without touching unrelated resources.'),glossary={'Principal':'Identity that requests an operation.','Least privilege':'Only the authority necessary for the intended task.','Shared responsibility':'Service-specific division of provider and customer operational duties.','Implicit denial':'No applicable permission grants the operation under the model.'},
rehearsal=dict(scope='Fictional exact-pair policy model; no cloud IAM evaluation or traffic.',states=[state('Baseline',['Allow (read, lesson/receipt)','No matching deny'],'The supplied pair is allowed.','Real policies require all applicable context.'),state('Fault',['Matching allow remains','Matching explicit deny added'],'Explicit denial wins in this narrow teaching rule.','Inspect the intended restriction rather than escalating privileges.'),state('Recovery',['Matching deny removed','Read allowed; unrelated write still denied'],'The original narrow permission is restored.','Verify real positive/negative operations separately.')]),
quick=[q('Does authentication imply authorization?','No.','A known identity can still lack a requested permission.','Access boundaries'),q('Does a private subnet make data access safe by itself?','No.','Identity, policy, encryption and application behavior still matter.','Network vs identity'),q('What happens to the model’s unrelated write?','It remains implicitly denied.','The allow applies only to the exact read/resource pair.','Scope of permission')],
exams=[q('Who patches the guest OS in a typical customer-managed cloud VM?','The customer, subject to the selected service’s documented responsibility boundary.','Provider operation of physical infrastructure does not automatically manage guest software.','Responsibility'),q('Why not reuse that answer for every managed service?','The provider may operate different layers in a more abstracted service.','Responsibilities must be derived per service.','Service model'),q('A connection times out. Does that prove permission denial?','No; naming, routing, controls or service behavior may prevent delivery.','Classify the observed boundary before choosing a repair.','Failure classification'),q('A request reaches the service and is denied. What identity evidence matters?','The actual principal and session context, requested action/resource and applicable policy revisions.','The intended identity may differ from the credentials actually used.','Effective identity'),q('Why use temporary workload credentials where possible?','They reduce long-lived secret exposure and support scoped lifecycle management.','They still require correct policies and secure delivery.','Credential lifecycle'),q('What does explicit deny do in the local model?','It overrides an exact matching allow.','The model intentionally omits other provider evaluation features.','Teaching policy'),q('What is wrong with testing only as an administrator?','It does not establish that the intended workload identity has the correct minimal access.','Broad authority can hide policy defects.','Representative tests'),q('Name a recovery dependency often missed in encrypted backups.','Usable decryption keys and an authorized recovery identity.','Stored ciphertext is not recoverable without the relevant access path.','Recovery authorization'),q('What should a negative access test prove?','An operation outside the intended scope is rejected for the intended identity.','A positive test alone cannot establish least privilege.','Denial testing'),q('Why is this companion not an IAM validator?','It lacks provider syntax, wildcards, conditions, role/resource/organization policy interactions and live context.','Its output is only a supplied exact-pair exercise.','Model scope')]
),dict(id='ADD-CLOUD-002',subtitle='Place compute and data against an explicit failure set.',minutes=50,
definition='Cloud architecture combines compute, storage and network services across provider-defined failure boundaries. Availability zones are useful isolation units, but service scope, placement, capacity, data consistency and recovery dependencies determine whether an application survives a particular failure.',
purpose='Design a workload that can explain what happens after a host, zone or regional failure. Distinguish aggregate surviving compute from a complete recovery claim. Select storage according to access, durability, consistency and restoration requirements instead of assuming every cloud storage product behaves like a local disk.',
mental='Distributing replicas across rooms reduces some shared risks, but only if the power, entrances, stored state and staff are also available. Zone labels do not remove every common dependency. An application can have spare compute after a failure and still be unable to elect a writer or attach its data.',
components=['Compute placement: instance/container/function capacity, quotas and actual failure-domain distribution.','Storage semantics: block, file or object interface, replication scope, consistency and backup/restore behavior.','Traffic entry: name resolution, balancing, endpoint scope and surviving return paths.','State ownership: replication, quorum or fencing rules preventing conflicting writers.','Recovery contract: failure set, demand, survivor reserve, RTO, RPO and independently protected recovery material.'],
mechanism=['Start with the business operation and named failure set. A design that tolerates one zone loss may not tolerate two, a region loss or shared identity failure. Record those distinctions explicitly.','Map each resource’s actual scope. A zonal block volume can constrain a workload’s placement; a regional managed service has a different operational contract. Verify the selected product’s current documentation rather than assuming all resources span zones.','Calculate a simple survivor envelope before considering detailed placement. Three zones each with 60 supplied units provide 180 normally, 120 after one loss and 60 after two. Against demand 100, one loss fits and two do not. These numbers exclude placement, scaling delay and quota limits.','Check data ownership and usable replication independently of compute. Replication can copy corruption, and asynchronous replicas may lag. Availability and durability claims need their own evidence and failure assumptions.','Rehearse recovery to an isolated environment, validate the intended operation and reconcile the recovery point. Account for keys, secrets, DNS, deployment artifacts and operator access, not only machine creation.'],
flow=[('Name failures','State one-zone, multi-zone or region scope explicitly.'),('Place dependencies','Map compute, data, identity and traffic entry to actual scopes.'),('Check survivors','Calculate capacity and verify state/ownership constraints.'),('Test recovery','Measure the original operation and accepted data point on a real target.')],
comparison=[['Multi-zone availability','Service continuity through specified zone failures','Depends on capacity, placement and state design'],['Durability','Retention of acknowledged data under stated conditions','Does not imply immediate availability'],['Replication','Maintains additional copies under a policy','Can propagate corruption or have lag'],['Backup','Retains an earlier recoverable state','Must be independently protected and restored in tests']],
example='The companion’s three equal domains each contribute 60 abstract units. The fault removes two domains, leaving 60 against demand 100. Its recovery state restores one domain, leaving 120, which fits the arithmetic demand. It does not allocate cloud capacity, measure failover or guarantee that data is available in the surviving domains.',
commands=[cmd('capacity')],
configuration='Before an owned cloud rehearsal, record placement and service scopes, quotas, data ownership and the exact allowed fault. Confirm a tested backup and recovery credentials. Use provider-supported failure/recovery procedures within that disposable target. Restore policy and routing through the recorded change plan; do not infer that deleting/recreating resources restores their data.',
production='Reserve survivor capacity and account for scaling and replacement time. Keep recovery artifacts and keys usable when the primary domain is unavailable. Define which consistency tradeoffs and data-loss windows are acceptable; architecture diagrams must state rather than hide those decisions.',
troubleshooting=[('Replicas exist but only one zone serves','Inspect actual placement, eligible endpoints and shared storage constraints.'),('Compute recovers but writes fail','Check data ownership, storage attachment, credentials and application consistency.'),('Failover exceeds objective','Measure detection, decision, provisioning, restore and validation, not only traffic switching.'),('Backup restored stale data','Compare actual recoverable point age and acknowledged transactions with the RPO target.')],
security='Apply equivalent policy at the recovery location and protect replication/backup paths. A recovery environment with relaxed identity or network rules can expose data precisely when operators are under pressure.',
performance='Cross-zone or cross-region communication changes latency, transfer cost and consistency behavior. Aggregate units are a planning envelope, not an application benchmark. Measure representative traffic and storage latency before accepting the design.',
mistakes=['Treating zone count as proof of independence.','Counting compute without storage/identity dependencies.','Calling replication a backup.','Ignoring quotas and replacement delay.','Confusing RTO with RPO.'],ports='Cloud compute and storage products expose service-specific network interfaces. The capacity model uses no network and makes no packet-forwarding or provider endpoint claim.',prerequisites=['ADD-CLOUD-001','ADD-INFRA-002'],related=['capstone-final','ADD-CLOUD-003'],artifacts=artifact,sources=[refs[2],refs[5]],
lab=dict(objective='Calculate survivor capacity and identify the unproven requirements for a complete cloud recovery.',requirements='Python 3.10+ and a notebook; all capacities are supplied abstract units.',topology=['Zone A: 60 units','Zone B: 60 units','Zone C: 60 units','Demand: 100 units'],steps=['Calculate capacity after zero, one and two zone losses.','Run the capacity case and compare 180/60/120 with the documented baseline/fault/recovery order.','Place a zonal data dependency into the design and explain why the compute result alone is insufficient.','Define an accepted recovery point and writer-fencing rule.','Draft an isolated target rehearsal including quotas, keys, DNS and the original application probe.','State the failure sets this design does not cover.'],verification='The model fits demand at 180 and 120 but not 60. The notebook separately addresses data, ownership, identity, quotas and measured recovery; none are claimed from arithmetic.',troubleshooting='Check failed-domain counts and units. Heterogeneous domains or shared resources need a different capacity model; do not average away the weakest constraint.',challenge='Demand rises to 130 with one zone unavailable. Decide whether the design still meets the declared failure objective and which additional evidence a capacity increase needs.',cleanup='No resources are created. An actual future rehearsal must remove only its owned resources after preserving required evidence/data and confirming cost cleanup.'),glossary={'Availability zone':'Provider-defined infrastructure failure-isolation scope within a region.','Quorum':'Required agreement threshold for an operation or ownership decision.','Fencing':'Preventing an old owner from continuing authoritative writes.','Survivor capacity':'Usable capacity remaining after the specified failure.'},
rehearsal=dict(scope='Supplied equal-domain capacity; no cloud provisioning, replication or failover.',states=[state('Baseline',['3 × 60 = 180 units','Demand 100'],'Aggregate capacity fits before failures.','Check placement and data dependencies separately.'),state('Fault',['Two domains unavailable','Survivor capacity 60 < 100'],'The stated demand no longer fits the model.','Apply the declared degraded-service or recovery policy.'),state('Recovery',['One failed domain restored','Survivor capacity 120 ≥ 100'],'Arithmetic capacity fits again; application recovery is still unproven.','Validate actual state ownership and original transactions.')]),
quick=[q('How much survives one loss from three 60-unit zones?','120 units.','Two supplied domains remain.','Survivor arithmetic'),q('Does replication replace a backup?','No.','It may propagate corruption or lack an earlier protected recovery point.','Data protection'),q('Does spare compute prove data access?','No.','Storage scope, credentials and ownership may still prevent use.','Dependency completeness')],
exams=[q('What remains after two 60-unit zone losses from three zones?','60 units, insufficient for demand 100.','Only one supplied domain survives.','Failure envelope'),q('Demand is 130 after one zone fails. Does 120 fit?','No; it is short by ten units.','A design must be re-evaluated when workload demand changes.','Capacity drift'),q('Why distinguish service scope from region location?','A resource in a region may still be zonal or have specific replication behavior.','Location labels do not establish failure tolerance.','Resource scope'),q('What can go wrong with two writable recovery sites?','Conflicting authoritative writes can create split-brain or inconsistent state.','Ownership and fencing need explicit verification.','Writer safety'),q('Why is asynchronous replication relevant to RPO?','The recoverable copy can lag behind acknowledged writes.','Data-point age and loss must be measured, not assumed zero.','Replication lag'),q('Which times contribute to RTO beyond restore runtime?','Detection, decision, preparation/provisioning, validation and client recovery within the agreed scope.','A narrow timer can understate actual disruption.','Recovery measurement'),q('Why keep recovery keys outside the primary failure dependency?','Otherwise the backup may be intact but inaccessible during the same outage.','Recoverability requires usable authorization.','Independent recovery'),q('What can invalidate an aggregate capacity calculation?','Placement constraints, quotas, unequal resources, storage bottlenecks or shared dependencies.','A scalar sum omits these operational limits.','Model limits'),q('Why test policy at the recovery site?','Security and access behavior must remain correct after cutover.','Availability without intended policy is not acceptable recovery.','Recovery controls'),q('What does this companion actually prove?','Correct supplied capacity arithmetic and input boundaries.','It creates no cloud resource and measures no failover.','Evidence scope')]
),dict(id='ADD-CLOUD-003',subtitle='Control spending and infrastructure changes without losing recovery state.',minutes=55,
definition='Cloud cost control connects resource usage, prices, ownership and action policies. Infrastructure as code describes intended resources and tracks their managed state, but reviewable configuration is not proof of deployment or recovery. Budgets, tags, plans, state protection and restore tests serve different operational purposes.',
purpose='Estimate a small workload’s cost transparently and detect a proposed increase before deployment. Assign an accountable owner and cleanup policy to resources, protect infrastructure state and verify that backups restore useful data. Avoid interpreting a budget alert as a universal spending cap.',
mental='A budget is an alarm and a plan is a proposed shopping list. Neither automatically locks the cash register. Provider billing can arrive late, actions have scope and permissions, and running resources can continue charging. Infrastructure state is an operational map that may contain sensitive values; it needs protection even when configuration output is redacted.',
components=['Cost model: quantities, units, rate date/region, duration and explicit exclusions.','Ownership tags: accountable owner, environment and lifecycle identifiers with an enforcement process.','Budget policy: thresholds, recipients/actions, data latency and escalation/cleanup behavior.','IaC plan/state: proposed changes, actual managed identities, drift, locking and sensitive data.','Recovery evidence: protected copies, usable credentials/keys, application restoration and verified resource cleanup.'],
mechanism=['Build an estimate from declared usage and rates, then list excluded cost drivers such as requests, snapshots, transfer paths, gateways, taxes or support. The companion uses fictional currency units only, so its total is a reproducible exercise rather than a vendor quote.','Apply ownership and lifecycle metadata consistently, but recognize that tags alone neither enforce access nor delete expired resources. Validate missing owners and route alerts to an accountable team.','Review a plan before apply: intended target/account, additions, replacements, deletions and data implications. A plan can become stale through drift or changed inputs; preserve review context and coordinate state changes.','Protect state with restricted access, encryption and supported locking/version recovery. Marking a value sensitive generally controls display; it does not mean the value is absent from all state or plan artifacts. Provider/runtime features must be checked for the exact workflow.','Reconcile actual billed usage and actual resource inventory after changes. Budget notifications can lag and configured actions are not a universal instantaneous hard cap. Test backups and cleanup, then verify the original application and retained data rather than assuming destroy or rollback is always safe.'],
flow=[('Estimate','Declare usage/rates and excluded charges.'),('Review','Check ownership, plan changes, target and sensitive state.'),('Control','Observe budget signals and execute scoped authorized actions.'),('Recover and reconcile','Restore known state/data and verify actual resource/cost outcomes.')],
comparison=[['Estimate','Calculation under assumptions','Not an invoice or price guarantee'],['Budget alert','Notification based on monitored cost/usage','Can lag and does not universally stop spending'],['Tag','Metadata for ownership/accounting','Needs policy to become an enforced lifecycle control'],['IaC state','Managed resource mapping and attributes','Can contain secrets and needs protected recovery']],
example='Fictional rates are 0.05 units per instance-hour, 0.10 per storage unit-month and 0.08 per egress unit. Three instances for 730 hours plus 100 storage units and 50 egress units total 109.50 + 10 + 4 = 123.50. Six instances raise the total to 233, above a 150 budget. The companion also changes and exactly restores a private JSON plan file; it never runs Terraform.',
commands=[cmd('cost')],
configuration='For an owned disposable cloud project, set the account/region, approved budget, owner and cleanup criteria before provisioning. Review the provider-specific plan and permissions, retain protected state history and verify the proposed destructive actions explicitly. On failure, choose a tested forward fix or restore procedure that respects persistent data; do not assume reverting source files or running destroy restores prior service.',
production='Track both service cost and unit economics under a defined workload. Reconcile estimates with actual usage and provider billing delay. Keep backup retention, transfer, idle allocations and abandoned resources visible. Use cost actions with known scope and failure handling rather than relying on an email nobody owns.',
troubleshooting=[('Bill exceeds estimate','Check omitted services, quantity units, region/rate changes, transfer paths and billing period before blaming one instance type.'),('Budget alert arrives late','Inspect the provider’s data refresh and threshold/action behavior; it is not a synchronous admission controller.'),('Plan proposes unexpected replacement','Inspect configuration, state drift, provider/version changes and immutable attributes before apply.'),('State marked sensitive but secrets appear in artifacts','Restrict and inspect state/plan handling; display redaction is not universal data removal.')],
security='Treat state and saved plans as potentially secret-bearing artifacts. Keep them out of public repositories and logs, use minimum required provider authority and protect recovery keys. The local exercise uses only synthetic ownership and instance counts, never real credentials.',
performance='Cost reduction must preserve service objectives and survivor capacity. Reducing replicas or storage performance can lower an estimate while violating latency or recovery requirements. Evaluate representative workload and failure conditions before accepting savings.',
mistakes=['Calling a budget notification a hard cap.','Using fictional rates as current provider prices.','Assuming tags delete resources.','Treating sensitive display flags as absence from state.','Reverting IaC text without checking deployed state/data.'],ports='The offline estimate and file restore need no network. Real IaC uses authenticated provider APIs and a separately secured state backend; neither is contacted here.',prerequisites=['ADD-CLOUD-001','ADD-CLOUD-002','ADD-INFRA-003'],related=['s9-g4-t4','capstone-final'],artifacts=artifact,sources=[refs[3],refs[4],refs[5]],
lab=dict(objective='Reproduce a fictional cost increase and exact local plan rollback while specifying real operational controls.',requirements='Python 3.10+ and a notebook; no Terraform installation, cloud account or rate lookup is required for this fictional exercise.',topology=['Quantity/rate assumptions','Cost components','150-unit budget comparison','Owned JSON plan restoration'],steps=['Calculate compute, storage and egress components for three instances using the stated units.','Repeat for six instances and predict remaining budget.','Run the cost case; verify 123.50/233.00/123.50 and exact plan restoration.','Add a written list of excluded charges and explain why this is not a provider quote.','Define ownership tags, alert routing, a scoped cleanup policy and what happens if an action fails.','Draft an IaC review/rollback checklist covering target identity, state protection, drift, data and post-change service verification.'],verification='Baseline/recovery fit budget; fault exceeds it by 83. Exact file restoration and cleanupVerified are true. No bill or cloud resource is changed.',troubleshooting='Check hours, counts and per-unit rate conversions before interpreting a total. A real estimate requires current service/region-specific rates and actual usage; use the provider calculator for that separate task.',challenge='Cut one zone’s replicas to reduce cost. Explain which capacity, availability and data-recovery checks must still pass before accepting the change.',cleanup='The companion removes only its new plan directory. A future cloud exercise must inventory and verify removal of its owned chargeable resources while retaining protected required data.'),glossary={'Drift':'Difference between intended/tracked and actual infrastructure state.','State locking':'Coordination preventing conflicting state updates under a supported backend workflow.','Cost allocation tag':'Metadata used to attribute usage/cost under provider-specific rules.','Budget action':'A configured response with defined scope, permissions and failure behavior.'},
rehearsal=dict(scope='Fictional rates and actual local JSON restoration; not provider pricing, billing or Terraform execution.',states=[state('Baseline',['3 × 730 × 0.05 = 109.50','Storage 10; egress 4; total 123.50','Budget 150'],'The supplied estimate fits with 26.50 remaining.','List excluded charges and validate rates for any real estimate.'),state('Fault',['Instance count doubles to 6','Total 233.00; remaining -83.00'],'The fictional budget is exceeded; no spending-stop action exists in this model.','Review the proposed quantity change and its service reason.'),state('Recovery',['Original plan bytes restored','Total 123.50; private directory removed'],'The local plan and calculation return to baseline.','Real deployed resources and billed usage would still need reconciliation.')]),
quick=[q('Is the cost exercise a provider price quote?','No; every rate is fictional.','It teaches transparent quantities and units.','Estimate scope'),q('Does a budget alert always stop spending?','No.','Notifications and actions have latency, scope and permissions.','Budget behavior'),q('Can state contain sensitive values despite redacted output?','Yes.','Display controls do not guarantee absence from artifacts.','State protection')],
exams=[q('Calculate compute cost for three instances at the supplied rate and hours.','109.50 fictional units.','3 × 730 × 0.05 = 109.50.','Unit arithmetic'),q('What is the six-instance total including storage and egress?','233.00 fictional units.','219 compute + 10 storage + 4 egress.','Component aggregation'),q('How far over the 150 budget is that total?','83 units.','233 minus 150 equals 83.','Budget gap'),q('Name four possible charges excluded from this example.','Requests, snapshots, gateways and support or taxes, among other service-specific costs.','An honest estimate states its boundaries.','Cost completeness'),q('Why is an owner tag insufficient lifecycle control?','Someone or an enforced process must act on it and verify cleanup.','Metadata alone does not remove resources.','Ownership action'),q('An IaC plan wants to replace a data volume. What should happen before apply?','Inspect why, protect/test data recovery and obtain the intended destructive-change decision.','A syntactically valid plan can still cause unacceptable data loss.','Plan review'),q('Why protect saved plans as well as state?','They may carry sensitive values and actionable infrastructure details.','Redaction in terminal output does not secure stored artifacts.','Artifact confidentiality'),q('Does restoring the local JSON plan restore cloud infrastructure?','No; the companion contacts no provider.','Actual deployment state and data must be reconciled separately.','Intent vs actual'),q('How can cost optimization undermine resilience?','Removing capacity or protection can break survivor demand, latency or recovery objectives.','Evaluate savings against the agreed failure set and SLOs.','Tradeoffs'),q('What evidence closes a real disposable cloud exercise?','Owned resource inventory, verified cleanup/cost follow-up, retained required backups and revoked temporary access.','A successful local command alone may leave chargeable resources or credentials.','Operational closure')]
)]
if __name__=='__main__': write_batch('33',lessons)
